<template>
  <main class="control"><header><div><h2>Control de combustible</h2><p>Consulta de consumo por actividad. Modelo de control inspirado en PF-088; esta pantalla no permite modificaciones.</p></div><span class="readonly">Solo lectura</span></header>
    <section class="filters"><label>Finca<select v-model="fincaId" @change="cargar"><option value="">Seleccione</option><option v-for="f in fincas" :key="f.id" :value="f.id">{{ f.code }} - {{ f.name }}</option></select></label><label>Desde<input v-model="desde" type="date" @change="cargar"/></label><label>Hasta<input v-model="hasta" type="date" @change="cargar"/></label></section>
    <section class="sheet"><div class="sheet-title"><strong>MODELO DE CONTROL Y CAPTACIÓN DE DEMANDA DE COMBUSTIBLE</strong><span>{{ desde }} al {{ hasta }}</span></div><p v-if="cargando" class="empty">Cargando control…</p><p v-else-if="!fincaId" class="empty">Seleccione una finca para consultar el control.</p><p v-else-if="!reporte?.lineas.length" class="empty">No hay salidas de combustible asociadas a actividades en el período.</p><div v-else class="table-wrap"><table><thead><tr><th rowspan="2">Actividad</th><th rowspan="2">U/M</th><th rowspan="2">Nivel de actividad</th><th colspan="3">Real del período</th><th colspan="3">Acumulado anual</th><th rowspan="2">Índice permisible</th><th rowspan="2">Desv. real</th><th rowspan="2">Estado</th></tr><tr><th>Nivel act.</th><th>Consumo</th><th>Índice</th><th>Nivel act.</th><th>Consumo</th><th>Índice</th></tr></thead><tbody><tr v-for="l in reporte.lineas" :key="l.laborId"><td><strong>{{ l.actividad }}</strong></td><td>{{ l.unidadMedida || '—' }}</td><td>{{ l.nivelActividad || '—' }}</td><td>{{ n(l.nivelPeriodo) }}</td><td>{{ n(l.consumoPeriodo) }}</td><td>{{ n(l.indicePeriodo) }}</td><td>{{ n(l.nivelAcumulado) }}</td><td>{{ n(l.consumoAcumulado) }}</td><td>{{ n(l.indiceAcumulado) }}</td><td>{{ n(l.indicePermisible) }}</td><td :class="{ excess: (l.desviacion || 0) > 0 }">{{ n(l.desviacion) }}</td><td><span :class="(l.desviacion || 0) > 0 ? 'bad' : 'ok'">{{ (l.desviacion || 0) > 0 ? 'Excede' : 'Dentro' }}</span></td></tr></tbody><tfoot><tr><td colspan="3">TOTAL</td><td>{{n(total('nivelPeriodo'))}}</td><td>{{n(total('consumoPeriodo'))}}</td><td>{{n(indiceTotal('consumoPeriodo','nivelPeriodo'))}}</td><td>{{n(total('nivelAcumulado'))}}</td><td>{{n(total('consumoAcumulado'))}}</td><td>{{n(indiceTotal('consumoAcumulado','nivelAcumulado'))}}</td><td colspan="3"></td></tr></tfoot></table></div></section>
  </main>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import FincaService from '@/services/FincaService'
import ControlCombustibleService, { type ControlCombustible } from '@/services/ControlCombustibleService'
import { notify } from '@/composables/useNotification'
const hoy=new Date(), desde=ref(new Date(hoy.getFullYear(),hoy.getMonth(),1).toISOString().slice(0,10)), hasta=ref(hoy.toISOString().slice(0,10)), fincaId=ref(''), fincas=ref<any[]>([]), reporte=ref<ControlCombustible|null>(null), cargando=ref(false)
const n=(v?:number)=>v==null?'—':v.toLocaleString('es-CU',{maximumFractionDigits:4})
const total=(campo:'nivelPeriodo'|'consumoPeriodo'|'nivelAcumulado'|'consumoAcumulado')=>reporte.value?.lineas.reduce((s,l)=>s+(l[campo]||0),0)||0
const indiceTotal=(consumo:'consumoPeriodo'|'consumoAcumulado',nivel:'nivelPeriodo'|'nivelAcumulado')=>{const nvl=total(nivel);return nvl?total(consumo)/nvl:0}
async function cargar(){reporte.value=null;if(!fincaId.value)return;cargando.value=true;try{reporte.value=(await ControlCombustibleService.consultar(fincaId.value,desde.value,hasta.value)).data}catch(e){console.error(e);notify.error('Control de combustible','No se pudo cargar el reporte.')}finally{cargando.value=false}}
onMounted(async()=>{try{fincas.value=(await FincaService.getAll()).data||[];if(fincas.value.length===1){fincaId.value=fincas.value[0].id;await cargar()}}catch(e){console.error(e);notify.error('Control de combustible','No se pudieron cargar las fincas.')}})
</script>
<style scoped>.control{max-width:1500px;margin:auto;padding:20px}.control>header,.filters,.sheet-title{display:flex;justify-content:space-between;align-items:center;gap:16px}.control h2{margin:0;color:#17365d}.control p{color:#64748b}.readonly{background:#e0f2fe;color:#075985;padding:7px 10px;border-radius:6px;font-weight:700}.filters,.sheet{background:#fff;border:1px solid #cbd5e1;border-radius:8px;padding:16px;margin-top:16px}.filters{justify-content:flex-start}.filters label{display:grid;gap:5px;font-size:.85rem;font-weight:700}.filters select,.filters input{min-width:180px;padding:8px;border:1px solid #94a3b8;border-radius:4px}.sheet-title{border-bottom:2px solid #1e3a5f;padding-bottom:12px;color:#1e3a5f}.sheet-title span{font-size:.85rem}.table-wrap{overflow:auto;margin-top:16px}table{width:100%;border-collapse:collapse;font-size:.85rem}th,td{border:1px solid #94a3b8;padding:8px;text-align:right;white-space:nowrap}th{background:#dbeafe;text-align:center}td:first-child,td:nth-child(2),td:nth-child(3),tfoot td:first-child{text-align:left}tfoot{background:#eff6ff;font-weight:800}.ok,.bad{display:inline-block;padding:3px 7px;border-radius:10px;font-weight:700}.ok{background:#dcfce7;color:#166534}.bad,.excess{background:#fee2e2;color:#b91c1c}.empty{padding:28px;text-align:center}@media(max-width:700px){.control>header,.filters{align-items:stretch;flex-direction:column}.filters select,.filters input{width:100%;box-sizing:border-box}}</style>
